#!/usr/bin/env bash
# ============================================================================
#  GSZ step120 — announcements + promos (dashboard + WhatsApp).
#  Admin composer targets all customers or buyers of one product, shows on the
#  account dashboard, and optionally pushes to verified WhatsApp numbers.
#  New: routes/adminAnnouncements.js, views/admin/announcements.ejs.
#  Patches: server.js, _shell_top.ejs, account.js, account/dashboard.ejs.
#  Migration: announcements table + whatsapp.announcement template.
#  Safe + idempotent; restores on any failure.
# ============================================================================
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step120-$TS"; TMP=$(mktemp -d)
PATCHED=(server.js views/admin/_shell_top.ejs routes/account.js views/account/dashboard.ejs)
NEW=(routes/adminAnnouncements.js views/admin/announcements.ejs)

echo "==> step120: announcements + promos"
mkdir -p "$BK"
for f in "${PATCHED[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
NEWHAD=()
for f in "${NEW[@]}"; do if [ -f "$GSZ/$f" ]; then NEWHAD+=("$f"); mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; fi; done
echo "    backup: $BK"
restore() {
  echo "!!  FAILED — restoring"
  for f in "${PATCHED[@]}"; do cp "$BK/$f" "$GSZ/$f"; done
  for f in "${NEW[@]}"; do keep=0; for h in "${NEWHAD[@]:-}"; do [ "$h" = "$f" ] && keep=1; done; if [ "$keep" = "1" ]; then cp "$BK/$f" "$GSZ/$f"; else rm -f "$GSZ/$f"; fi; done
  pm2 restart gsz >/dev/null 2>&1 || true; echo "!!  restored."
}
trap 'restore' ERR

echo "" | base64 -d > "$TMP/patch.js"
echo ""   | base64 -d > "$TMP/migrate.js"
echo "==> writing new files"
mkdir -p "$GSZ/routes" "$GSZ/views/admin"
echo "" | base64 -d > "$GSZ/routes/adminAnnouncements.js"
echo "" | base64 -d > "$GSZ/views/admin/announcements.ejs"
echo "==> applying patches"
node "$TMP/patch.js" "$GSZ"
echo "==> validating"
node --check "$GSZ/server.js"; node --check "$GSZ/routes/adminAnnouncements.js"; node --check "$GSZ/routes/account.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');['views/admin/announcements.ejs','views/admin/_shell_top.ejs','views/account/dashboard.ejs'].forEach(function(f){ejs.compile(require('fs').readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('    ejs ok '+f)})"
echo "==> migrating db"
( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/migrate.js" )
echo "==> restarting app"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
[ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
AC=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/admin/announcements || true)
[ "$AC" = "200" ] || [ "$AC" = "302" ] && echo "    /admin/announcements reachable ($AC): OK" || { echo "    /admin/announcements $AC"; false; }
trap - ERR; rm -rf "$TMP"
echo ""
echo "==> step120 OK ✅"
echo "    • New admin page: Announcements — post news/promos to all customers or buyers of one product."
echo "    • Shows on each customer's account dashboard; optional coupon chip."
echo "    • 'Also send to WhatsApp' pushes to verified numbers (resend anytime, no duplicates)."
